import Cars from "./Cars"
import { Component,React } from "react"

class Car extends React.Component{
    constructor(props){
        super(props)
    }

    render(){
        return
        <>{
        
        this.props.carItems.map((items,index)=> <Cars itemNumber={index +1} carObj={items}/>
        
        )
        
    }
    </>
    }
}

export {Car}
